
#pandas powerfull and flexible and easy to use open source data analysis and manupulations 

#pandas series (series is columns)

#import pandas 
import pandas as pd
import numpy as np

#series using list
country=['india','nepal','pakistan','us','uk']
print(pd.Series(country))
# series include index and its value at index
runs=[23,45,78,100,98,32,11,32,10,9,8]
print(pd.Series(runs,dtype='Int32'))

#custom Index 
marks=[30,60,80,90,100]
subject=['math','english','cs','sst','elctronics']

print(pd.Series(marks,index=subject,name='ayan ke marks '))

#series using dictonaries 

marks_dict={
    'math':40,
    'english':70,
    'science':90
}

marks_dict_series=pd.Series(marks_dict,name="my marks ")



#series attributes 
#size (no.of elements in the series )
print(marks_dict_series.size)

#dtype (series item datatype )
print(marks_dict_series.dtype)
 
#name (tell name  of the series)
print(marks_dict_series.name)

#is_uniqe
print(marks_dict_series.is_unique)

#index (give all index in one go )
print(marks_dict_series.index)

#values (get all values in one go )
print(marks_dict_series.values)


